use xiom.io;

enum Dice {
  D4,
  D6,
  D8,
  D10,
  D12,
  D20,
}

fn Dice.max_value(self) -> Int {
  match self {
    D4 => { return 4; }
    D6 => { return 6; }
    D8 => { return 8; }
    D10 => { return 10; }
    D12 => { return 12; }
    D20 => { return 20; }
  }
}

fn roll(d: Dice) -> Int {
  let max = d.max_value();
  return (max / 2) + 1;
}

fn main() -> Int {
  let d20 = Dice.D20;
  let d6 = Dice.D6;
  return roll(d20) + roll(d6);
}
